export function employeeStrip(selected) {
 return `<nav class="employee-strip" aria-label="Choose an employee">${people.map(p=>`<button data-workspace="${p.id}" aria-pressed="${p.id===selected}"><b>${p.name}</b><span>${p.department}</span></button>`).join('')}</nav>`;
}
function financeWork(step) {
 return `<div class="work-appbar excel-bar">${logo('ms-excel.svg','Excel · Monthly branch report')}<small>Excel runs the saved transformation</small></div><div class="work-body finance-work"><div class="incoming-files"><section><b>North.csv</b><span>Vendor / Amount</span><code>Acme Ltd / 1,200</code></section><section><b>East.xlsx</b><span>Supplier / Total</span><code>ACME LTD. / 1,200</code></section><section><b>West.csv</b><span>Payee / Cost</span><code>North Office / 850</code></section></div><div class="work-chat-excerpt ${step?'work-chat-compact':''}">${logo('claude.svg','Earlier · Claude helped build the transformation')}<p><b>Priya:</b> “Normalize these headers and vendor spellings. Flag duplicate invoices. Do not delete rows.”</p><p><b>Claude:</b> “Standardize the fields, then route repeated invoice IDs to a review table.”</p></div>${step?table(['Vendor','Invoice','Amount','Review'],[['Acme Ltd','N101','$1,200','Ready'],['Acme Ltd','N101','$1,200',step>1?'Excluded duplicate':'Possible duplicate'],['North Office','W203','$850','Ready']],[1]):'<div class="work-empty">Saved transformation ready.<br><strong>One refresh. Three branch formats.</strong></div>'}${step?`<p class="work-result">${step>1?'Priya confirms the duplicate. Two rows are ready; the original files are preserved.':'One possible duplicate needs Priya’s judgment. Nothing was silently discarded.'}</p>`:''}</div>`;
}
function workSurface(id,step) {
 if(id==='priya')return financeWork(step);
 if(id==='ben')return `<div class="work-appbar excel-bar">${logo('ms-excel.svg','Excel · Four Friday pipeline snapshots')}${logo('copilot.webp','Copilot')}</div><div class="work-body">${table(['Opportunity','Oct 16','Oct 23','Oct 30','Nov 6'],[['Atlas renewal','Oct 30','Nov 6','Nov 20','Nov 20'],['Beacon expansion','Oct 23','Nov 6','Nov 27','Nov 27'],['Delta rollout','Oct 30','Nov 13','Nov 27','Nov 27'],['Harbor services','Nov 20','Nov 20','Nov 20','Nov 20']],step?[0,1,2]:[])}${chat('BEN’S SAVED PROMPT','Flag deals with two date changes and no new buyer activity.','prompt')}${step?chat('COPILOT · CHECK AGAINST THE HIGHLIGHTED ROWS','Three deals moved twice. <mark>Check buyer evidence with these reps.</mark> Ben verifies the source rows before coaching.'):''}</div>`;
 if(id==='nina')return `<div class="work-appbar teams-bar">${logo('ms-teams.svg','Teams · Ask Ops')}<small>Department-built assistant · 6 users</small></div><div class="work-body">${chat('NINA','What kept coming back this week? Group the issues and show me the original cases.','prompt')}${step?`${chat('ASK OPS','18 selected escalations: <mark>8 possible handoff issues</mark>, 6 billing questions, 4 access requests. Review the originals before accepting a pattern.')}<div class="work-source-links"><button data-detail="source:CASE-201">CASE-201 · Missing receiving owner ↗</button><button data-detail="source:CASE-204">CASE-204 · Handoff without owner ↗</button></div><p class="work-result">Nina checks the evidence and rejects weak groupings in the morning huddle.</p>`:'<div class="work-empty">The useful bot already exists.<br><strong>Other departments have not seen it.</strong></div>'}</div>`;
 if(id==='marcus')return `<div class="phone-scene"><div class="practice-phone"><div class="phone-speaker"></div><div class="work-appbar">${logo('grok.svg','Grok · Practice')}<small>Captioned role-play</small></div><div class="phone-captions">${step<2?chat('MARCUS','Play a frustrated customer. Interrupt me if my answer is vague.','prompt'):''}${step===1?chat('CUSTOMER · AI ROLE-PLAY','“I have explained this to three teams. Who is actually helping me?”'):''}${step>=2?`${chat('MARCUS','“Someone will get back to you.”','prompt')}${chat('CUSTOMER · AI ROLE-PLAY','“Who? And when?”')}`:''}${step>=3?chat('MARCUS · SECOND TRY','“I am your contact. I will confirm the owner and call you by 3 PM.”','improved'):''}</div></div><p class="phone-context">Generic scenario.<br>No customer names or records.<br><b>Private chat stays private.</b></p></div>`;
 if(id==='ava')return `<div class="work-appbar">${logo(step===2?'zendesk.svg':'ms-outlook.svg',step===2?'Zendesk · Before the draft':'Outlook · Customer reply')}${logo('copilot.webp','Copilot')}</div><div class="work-body">${step===2?`<div class="ticket-history">${['Monday · Implementation notes saved in another task','Tuesday · Customer reassigned to Service','Wednesday · Receiving owner still unclear','Thursday · Customer repeats setup details','Friday · Ava asks Operations for context','Friday · Ava checks the promised callback'].map((t,i)=>`<p><b>Ticket ${201+i}</b>${t}</p>`).join('')}</div><p class="work-result">Six records inspected before Ava could write a responsible reply.</p>`:`${chat('AVA’S ORIGINAL DRAFT','I understand you have already explained this. I have asked Operations to confirm who owns the next step and will update you today.','draft')}${chat('AVA → COPILOT','Make this warmer and shorter without promising anything I can’t deliver.','prompt')}${step?chat('COPILOT · AVA REVIEWS BEFORE SENDING','“You shouldn’t have to repeat the details. I’m confirming the owner with Operations and will update you today.”','improved'):''}`}</div>`;
 if(id==='elena')return `<div class="work-appbar">${logo('ms-excel.svg','Excel · Thursday commitments')}<small>Update due 4 PM</small></div><div class="work-body">${table(['Commitment','Owner','Due'],[['Confirm rollout scope','Unassigned','Nov 12'],['Validate branch totals','Priya','Nov 9'],['Send account update','Marcus','Nov 10']])}${step?`<div class="abandoned-chat ${step===2?'attempt-closed':''}">${logo('copilot.webp','Copilot · Her first attempt')}${chat('ELENA','Help with my projects.','prompt')}${chat('COPILOT','Set clear goals, prioritize your tasks, and communicate regularly with stakeholders.')}</div>`:'<div class="work-empty">Meeting notes and email updates still need comparing.</div>'}${step===2?'<p class="work-result warning">3:42 PM. Elena returns to copying dates and owners by hand. She wants help with this task.</p>':''}</div>`;
 if(id==='daniel')return `<div class="work-appbar teams-bar">${logo('ms-teams.svg','Teams · Ask Parkside')}<small>Company assistant · Approved SharePoint sources</small></div><div class="work-body">${step<2?chat('EMPLOYEE','How do I escalate a client issue?','prompt'):''}${step?`${step<2?chat('ASK PARKSIDE','Name one accountable owner, record the next update date, and link the receiving team to the original case.'):'<p class="work-result">Approved guidance retrieved with its source.</p>'}<button class="work-source" data-detail="procedure">Customer Escalation Procedure · §3 ↗</button>`:'<div class="work-empty">An approved starting point for everyone.</div>'}${step===2?'<div class="launch-feedback"><b>Daniel’s Teams announcement</b><p>“It’s live. Try it and tell us what you think.”</p><p><strong>Feedback: “Thanks!” · 👍</strong></p><span>Usage report: opens and active users.<br>Still missing: which real tasks improved?</span></div>':''}</div>`;
 if(id==='dana')return `<div class="work-appbar">${logo(step?'claude.svg':'ms-powerpoint.svg',step?'Claude · Board preparation':'PowerPoint · AI rollout update')}</div><div class="work-body">${step?`${chat('DANA','Act like a skeptical board member. Which claim would you challenge? What evidence should I bring?','prompt')}${chat('CLAUDE','You show access and usage. <mark>What changed in the time it takes to finish work across departments?</mark> Bring a specific before-and-after workflow, not just an adoption total.')}${chat('DANA','That’s a better question. I will ask how the weekly brief is actually prepared.','improved')}`:'<div class="rollout-metrics"><section><strong>150</strong><span>Copilot licenses assigned</span></section><section><strong>Live</strong><span>Company assistant</span></section><section><strong>Working</strong><span>Sales forecast review</span></section></div><blockquote class="work-bigquote">“I’ve seen what Sales can do. And Claude helps me prepare for every board meeting.”</blockquote>'}</div>`;
 return `<div class="work-appbar teams-bar">${logo(step===2?'claude.svg':'ms-teams.svg',step===2?'Claude · Dana’s received briefing':'Teams + Outlook · Leah’s Friday')}</div><div class="work-body">${step===2?`${chat('DANA','What should I take from this week’s department updates?','prompt')}${chat('CLAUDE · BASED ON WHAT WAS PROVIDED','Sales revised its forecast. Operations handled 18 escalations. Service responded to every inquiry.')}<p class="work-result warning">An accurate summary of the inputs. The recurring handoff issue was never assembled into the brief.</p>`:step?`<div class="friday-messages"><section><b>Leah → Sales</b><p>Which forecast changed, and why?</p><span>Ben: “Atlas moved to Nov 20. See Friday v4.”</span></section><section><b>Leah → Operations</b><p>Anything behind the volume?</p><span>Nina: “18 escalations. Northwind setup came back.”</span></section><section><b>Leah → Service</b><p>Is this the same customer?</p><span>Ava: “NW Services. Last update says Tuesday.”</span></section></div><div class="reconcile-note"><b>Still unresolved</b><span>Northwind = NW Services? Which Tuesday? Is a completed task a completed customer handoff?</span></div>`:'<div class="work-empty"><strong>Weekly briefing · Unfinished</strong><br>Sales total received. Ops summary received.<br>Owners, dates and assumptions still need checking.</div>'}</div>`;
}
export function renderWorkspace(state,personId=state.workspace||state.person) {
 const person=people.find(p=>p.id===personId)||people[3]; const id=person.id;const story=workspaceStories[id];const step=state.workSteps?.[id]||0;
 const done=step>=story.max;const peer=state.peer===id&&story.peer;
 const label=id==='marcus'?(step?'Replay captioned practice':story.action):step?story.done:story.action;
 return `<section class="employee-workspace"><div class="workspace-top"><span><b>${person.name}</b> · ${person.department}</span><button data-close-workspace>← Company view</button></div><div class="workspace-columns"><section class="work-surface ${id}">${workSurface(id,step)}</section><aside class="work-story"><blockquote>${story.quote}</blockquote>${peer?`<div class="peer-reveal"><small>WHO ELSE COULD USE THIS?</small><h3>${story.peerTitle}</h3><p>${story.peer}</p><div class="peer-task">${logo(id==='marcus'?'grok.svg':id==='nina'?'zendesk.svg':'ms-excel.svg',story.peerTool)}${id==='priya'?'<code>Supplier → Vendor<br>ACME LTD. → Acme Ltd<br>Check invoice N101 again…</code>':id==='ben'?'<code>This week’s total: $2.4m<br>Last week’s total: $2.5m<br>Date history: not compared</code>':id==='nina'?'<code>Open ticket → copy issue<br>Open next ticket → compare</code>':'<p>“Could I practice before my next call?”</p>'}</div></div>`:`<div><small>WHAT WORKS</small><p>${story.situation}</p></div><div class="work-consequence"><small>WHAT THE COMPANY DOESN’T SEE</small><p>${story.consequence}</p></div>`}<div class="workspace-actions"><button class="primary" data-work-action="${id}" ${done&&id!=='marcus'?'disabled':''}>${done&&id!=='marcus'?(id==='priya'?'Exception reviewed ✓':id==='ava'?'The hidden work is visible':id==='elena'?'Back to manual updates':story.done):label}</button>${story.peer?`<button data-peer="${id}">${peer?'Back to their situation':'Who else could use this? →'}</button>`:''}${id==='nina'&&step?'<button data-detail="source:CASE-201">Open original case ↗</button>':''}</div></aside></div>${employeeStrip(id)}</section>`;
}
export function workspaceHeading(state) {const id=state.workspace||state.person;return workspaceStories[id]?.title;}
